import React, { useState, useContext } from "react";
import AsyncSelect from "react-select/async";
import axios from "../utils/axiosInstance";
import GeneralContext from "./GeneralContext";

const Search = () => {
  const [selectedValue, setSelectedValue] = useState(null);
  const { refreshWatchlist } = useContext(GeneralContext);

  const loadOptions = (inputValue, callback) => {
    if (!inputValue) {
      callback([]);
      return;
    }

    axios
      .get(
        `https://financialmodelingprep.com/api/v3/search?query=${inputValue}&limit=10&exchange=NSE&apikey=YOUR_FMP_API_KEY`
      )
      .then((res) => {
        const options = res.data.map((stock) => ({
          value: stock.symbol,
          label: `${stock.name} (${stock.symbol})`,
        }));
        callback(options);
      });
  };

  const handleAdd = (selectedOption) => {
    if (selectedOption) {
      axios
        .post("/api/watchlist", { symbol: selectedOption.value })
        .then(() => {
          refreshWatchlist();
          setSelectedValue(null);
        })
        .catch((err) => {
          console.error("Error adding stock:", err.message);
        });
    }
  };

  return (
    <div className="search-wrapper">
      <AsyncSelect
        cacheOptions
        loadOptions={loadOptions}
        defaultOptions
        value={selectedValue}
        onChange={handleAdd}
        placeholder="Search by stock name or symbol..."
      />
    </div>
  );
};

export default Search;
